insert into change_headers (id, ts) values (78, '2026-11-23') on duplicate key update ts = values(ts);
insert into change_descriptions (id, lang, description) values (78, 'ru', 'В калькулятор экспедиций добавлена галочка «Скорость экономики повышает награды экспедиций» — она учитывает скорость экономики при расчёте находок ресурсов и кораблей для Генерала и Коллекционера, как во вселенных с активным Orion.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'en', 'The expeditions calculator gains an "Economy speed increases expedition rewards" checkbox - it applies the economy speed when calculating resource and ship finds for the General and the Collector, as in universes with Orion active.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'pt', 'A calculadora de expedições ganha uma caixa de seleção «A velocidade da economia aumenta as recompensas de expedição» - aplica a velocidade da economia no cálculo das descobertas de recursos e naves do General e do Colecionador, como nos universos com Orion ativo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'de', 'Der Expeditionsrechner erhält ein Kontrollkästchen „Wirtschaftsgeschwindigkeit erhöht die Expeditionsbelohnungen“ - es berücksichtigt die Wirtschaftsgeschwindigkeit bei der Berechnung der Ressourcen- und Schiffsfunde von General und Sammler, wie in Universen mit aktivem Orion.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'pl', 'Kalkulator ekspedycji zyskuje pole wyboru „Prędkość ekonomii zwiększa nagrody z ekspedycji” - uwzględnia prędkość ekonomii przy obliczaniu znalezisk surowców i statków Generała i Kolekcjonera, jak we wszechświatach z aktywnym Orionem.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'es', 'La calculadora de expediciones gana una casilla «La velocidad de economía aumenta las recompensas de expedición»: aplica la velocidad de economía al calcular los hallazgos de recursos y naves del General y el Coleccionista, como en universos con Orion activo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'fr', 'Le calculateur d''expéditions gagne une case à cocher « La vitesse d''économie augmente les récompenses d''expédition » - elle applique la vitesse d''économie au calcul des trouvailles de ressources et de vaisseaux du Général et du Collecteur, comme dans les univers avec Orion actif.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'it', 'La calcolatrice delle spedizioni guadagna una casella «La velocità dell''economia aumenta le ricompense delle spedizioni» - applica la velocità dell''economia al calcolo dei ritrovamenti di risorse e navi del Generale e del Collezionista, come negli universi con Orion attivo.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'nl', 'De expeditiecalculator krijgt een selectievakje "De economische snelheid verhoogt de expeditiebeloningen" - het past de economische snelheid toe bij het berekenen van grondstoffen- en schepenvondsten voor de Generaal en de Verzamelaar, zoals in universums met actieve Orion.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'sk', 'Kalkulačka expedícií dostáva zaškrtávacie pole „Rýchlosť ekonomiky zvyšuje odmeny z expedícií“ - pri výpočte nálezov surovín a lodí Generála a Zberateľa zohľadňuje rýchlosť ekonomiky, ako vo vesmíroch s aktívnym Orionom.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'tr', 'Sefer hesaplayıcısına "Ekonomi hızı sefer ödüllerini artırır" onay kutusu eklendi - General ve Toplayıcı''nın kaynak ve gemi buluntularının hesaplanmasında ekonomi hızını uygular, Orion''ın aktif olduğu evrenlerdeki gibi.') on duplicate key update description = values(description);
insert into change_descriptions (id, lang, description) values (78, 'bs', 'Kalkulator ekspedicija dobiva potvrdni okvir "Brzina ekonomije povećava nagrade ekspedicija" - primjenjuje brzinu ekonomije pri izračunu nalaza resursa i brodova za Generala i Sakupljača, kao u univerzumima s aktivnim Orionom.') on duplicate key update description = values(description);
